import sys

def findSwapValues(A, B, N, M):
    sum_a = sum(A)
    sum_b = sum(B)

    diff = sum_b - sum_a

    if diff % 2 != 0:
        return -1

    target_diff = diff // 2

    set_b = set(B)

    for x in A:
        y = x + target_diff
        if y in set_b:
            return 1

    return -1

def main():
    input_data = sys.stdin.read().split()
    idx = 0

    if idx < len(input_data):
        N = int(input_data[idx])
        idx += 1
    else:
        return

    if idx < len(input_data):
        M = int(input_data[idx])
        idx += 1
    else
        return

    A = []
    for _ in range(N):
        if idx < len(input_data):
            A.append(int(input_data[idx]))
            idx += 1

    B = []
    for _ in range(M):
        if idx < len(input_data):
            B.append(int(input_data[idx]))
            idx += 1

    result = findSwapValues(A, B, N, M)
    print(result)

if __name__ == "__main__":
    main()
